import { transfer } from '../src/bank';

describe('transfer', () => {
  it('moves money', () => {
    expect(transfer(10, 'a', 'b')).toBe(true);
  });
  it('rejects overdraft', () => {
    expect(() => transfer(1e9, 'a', 'b')).toThrow();
  });
  it('rejects same account', () => {
    expect(() => transfer(1, 'a', 'a')).toThrow();
  });
});

